import{_ as e,o as t,c as o,ae as r}from"./chunks/framework.BX6FPmO9.js";const u=JSON.parse('{"title":"ADR：Backend Spec Layer — Data Contract + OPA","description":"","frontmatter":{},"headers":[],"relativePath":"adr/backend-spec-layer-opa.md","filePath":"adr/backend-spec-layer-opa.md"}'),n={name:"adr/backend-spec-layer-opa.md"};function s(d,a,c,l,i,p){return t(),o("div",null,[...a[0]||(a[0]=[r(`<h1 id="adr-backend-spec-layer-—-data-contract-opa" tabindex="-1">ADR：Backend Spec Layer — Data Contract + OPA <a class="header-anchor" href="#adr-backend-spec-layer-—-data-contract-opa" aria-label="Permalink to &quot;ADR：Backend Spec Layer — Data Contract + OPA&quot;">​</a></h1><p><strong>狀態</strong>：Accepted（POC）<br><strong>日期</strong>：2026-06-22</p><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>資料治理需要可審計、可測試、可版本控管的規則層，而非硬編碼於 application code。</p><h2 id="決策" tabindex="-1">決策 <a class="header-anchor" href="#決策" aria-label="Permalink to &quot;決策&quot;">​</a></h2><p>採用輕量 <strong>Backend Spec Layer</strong> 堆疊：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OpenAPI     → HTTP 形狀</span></span>
<span class="line"><span>Data Contract → 欄位語意、PII、owner</span></span>
<span class="line"><span>OPA Rego    → allow / need_approval / mask_fields / require_audit</span></span>
<span class="line"><span>CI          → opa test + lint:openapi + lint:handlers</span></span></code></pre></div><h3 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h3><ul><li><code>POST /api/metadata/access-requests/evaluate</code> — 政策預覽（驅動 HITL UI）</li><li><code>POST /api/metadata/access-requests</code> — 提交申請；<code>need_approval &amp;&amp; !approved</code> → 422</li></ul><h3 id="hitl" tabindex="-1">HITL <a class="header-anchor" href="#hitl" aria-label="Permalink to &quot;HITL&quot;">​</a></h3><p>前端<strong>不</strong>以 <code>tags.includes(&#39;PII&#39;)</code> 硬判；改呈現 OPA <code>reasons[]</code>，使用者點確認後送 <code>approved: true</code>。</p><h3 id="runtime" tabindex="-1">Runtime <a class="header-anchor" href="#runtime" aria-label="Permalink to &quot;Runtime&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>行為</th></tr></thead><tbody><tr><td>預設</td><td><code>evaluateAccessInProcess</code> 鏡像 Rego</td></tr><tr><td><code>OPA_URL</code> 設定</td><td><code>backend</code> 呼叫 OPA REST API</td></tr><tr><td>CI</td><td><code>pnpm run test:policies</code>（<code>opa test</code>）</td></tr></tbody></table><h2 id="為何不用-現階段" tabindex="-1">為何不用（現階段） <a class="header-anchor" href="#為何不用-現階段" aria-label="Permalink to &quot;為何不用（現階段）&quot;">​</a></h2><ul><li><strong>Pact</strong>：MSW + Vitest 整合測試已足 POC</li><li><strong>AsyncAPI</strong>：無 event bus</li><li><strong>Buf/Protobuf</strong>：全 HTTP monorepo</li></ul><h2 id="後果" tabindex="-1">後果 <a class="header-anchor" href="#後果" aria-label="Permalink to &quot;後果&quot;">​</a></h2><ul><li>需維護 Rego 與 in-process evaluator 語意一致（測試覆蓋）</li><li>Data Contract 與 catalog fixture 以 <code>datasetId</code> / fqn 對齊</li></ul>`,17)])])}const b=e(n,[["render",s]]);export{u as __pageData,b as default};
